  "model": "claude-haiku-4-5",
  "max_tokens": 800,
  "messages": [{
    "role": "user",
    "content": "You are a MedSpa intake concierge. A new inquiry just came in. Write a personalized 2-paragraph reply email AND score the lead. Return ONLY raw JSON, no markdown fences, no preamble.

Inquiry data:
- Name: {{ $json.clientName }}
- Service interest: {{ $json.service }}
- Lead source: {{ $json.leadSource }}
- Message from client: {{ ($json.message || 'No message — form submission only').replace(/"/g, '\"').replace(/
/g, ' ') }}

Background for the reply:
- Service tagline: {{ $json.serviceTagline }}
- Service details: {{ $json.serviceDetails }}
- Investment: {{ $json.servicePrice }}
- Standard CTA: {{ $json.serviceCta }}

Rules:
1. First paragraph acknowledges their SPECIFIC question or concern if they wrote a message (do NOT reference message if it was blank/form-only)
2. Second paragraph gives them the service info + CTA to book
3. Warm but professional, not salesy
4. Sign as YOUR_CLINIC_NAME
5. Score 0-100 based on: service value ($800+/treatment = higher), source quality (Referral/Website > TikTok/Facebook), message intent signal (specific question > browsing curiosity)

Return this exact JSON shape:
{
  "personalizedGreeting": "...",
  "personalizedBody": "Full HTML-safe reply body (2 paragraphs, <br/><br/> between)",
  "leadScore": 0-100,
  "leadTier": "HOT" | "WARM" | "COOL",
  "reasoning": "One sentence why this score",
  "suggestedResponse": "Instant" | "Within 4 hours" | "Next day OK"
}"
  }]
}

parameters.jsCode:
// Merge AI response with parsed inquiry. If AI failed, fall back gracefully.
const parsed = $('Parse Inquiry + Build Service Info').first().json;
const aiRaw  = $input.first().json;

let ai = null;
try {
  const text = aiRaw?.content?.[0]?.text || '';
  ai = JSON.parse(text);
} catch (e) {
  // AI failed or returned invalid JSON — fall back to template
  ai = null;
}

const hasAi = ai && ai.personalizedBody && typeof ai.leadScore === 'number';

return [{
  json: {
    ...parsed,
    aiUsed:            hasAi,
    personalizedBody:  hasAi ? ai.personalizedBody : null,
    personalizedGreeting: hasAi ? ai.personalizedGreeting : `Hi ${parsed.clientName || 'there'}`,
    leadScore:         hasAi ? ai.leadScore : 50,
    leadTier:          hasAi ? ai.leadTier : 'WARM',
    leadReasoning:     hasAi ? ai.reasoning : 'AI scoring unavailable — using default WARM',
    suggestedResponse: hasAi ? ai.suggestedResponse : 'Within 4 hours'
  }
}];
